BEGIN TRANSACTION;
CREATE TABLE "accounts" ("account_id" INTEGER PRIMARY KEY, "customer_id" INTEGER, "account_number" TEXT, "ifsc" TEXT, "upi_handle" TEXT, "debit_card" TEXT, "credit_card" TEXT, "balance" REAL, "opened_on" TEXT, "account_type" TEXT);
CREATE TABLE "branch_visits" ("visit_id" INTEGER PRIMARY KEY, "customer_id" INTEGER, "latitude" REAL, "longitude" REAL, "visit_pin" TEXT, "device_id" TEXT, "visited_at" TEXT, "duration_min" INTEGER);
CREATE TABLE "customers" ("customer_id" INTEGER PRIMARY KEY, "full_name" TEXT, "dob" TEXT, "gender" TEXT, "email" TEXT, "phone" TEXT, "aadhaar" TEXT, "pan" TEXT, "passport_no" TEXT, "address" TEXT, "pincode" TEXT, "city" TEXT, "segment" TEXT, "created_at" TEXT);
CREATE TABLE "kyc_documents" ("doc_id" INTEGER PRIMARY KEY, "customer_id" INTEGER, "passport_number" TEXT, "voter_epic" TEXT, "dl_no" TEXT, "verification_status" TEXT, "uploaded_at" TEXT);
CREATE TABLE "products" ("product_id" INTEGER PRIMARY KEY, "product_name" TEXT, "product_code" TEXT, "price" REAL, "stock" INTEGER, "category" TEXT);
CREATE TABLE "support_tickets" ("ticket_id" INTEGER PRIMARY KEY, "raised_by_email" TEXT, "callback_number" TEXT, "subject" TEXT, "priority" TEXT, "created_at" TEXT);
CREATE TABLE "system_logs" ("log_id" INTEGER PRIMARY KEY, "event_type" TEXT, "message" TEXT, "created_at" TEXT);
COMMIT;
